; ============================================== sub dumpLayer ====

dumpLayer:
; ---- for ( u16 i = 0; i < elCount; i++ ) {
        mov     word [dumpLayer__i], 0
.L640:
        mov     ax, [dumpLayer__i]
        mov     bx, [elCount]
        cmp     ax, bx
        jb      .L643                       ; unsigned <
        jmp     .L642
.L643:
; ---- putField( n )
        mov     ax, [dumpLayer__n]
        mov     [putField__n], ax
        call    putField
; ---- putField( i )
        mov     ax, [dumpLayer__i]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].x + dx )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__x + bx]
        mov     bx, [dumpLayer__dx]
        add     ax, bx
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].y + dy )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__y + bx]
        mov     bx, [dumpLayer__dy]
        add     ax, bx
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].w )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__w + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].h )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__h + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].minW )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__minW + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].minH )
        mov     ax, [dumpLayer__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__minH + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].overflowX )
        mov     ax, [dumpLayer__i]
        mov     bx, ax
        mov     al, [el__overflowX + bx]
