        mov     [putField__n], ax
        call    putField
; ---- putNumber( el[i].overflowY )
        mov     ax, [dumpLayer__i]
        mov     bx, ax
        mov     al, [el__overflowY + bx]
        xor     ah, ah                      ; bool -> u16
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
.L641:
        inc     word [dumpLayer__i]
        jmp     .L640
.L642:
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        ret

